#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <iostream>
using namespace fedspatial;static bool ld(const std::string&n,Matrix*x){return read_matrix("sync_gpu/tests/fixtures/sync_gpu/"+n,x);}int main(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sg(2,2);double a[]={0,0,1,.2,.3,1.1},b[]={0,0,1.5,1.5},q[]={1.2,-.4,.7};std::copy(a,a+6,s.a.begin());std::copy(b,b+4,k.a.begin());std::copy(q,q+3,z.a.begin());for(double&v:x.a)v=1;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sg(0,0)=.7;sg(1,1)=.4;sg(0,1)=sg(1,0)=.05;GpuContext c(0);double aa=0,ar=0,ra=0,rr=0,sy=0;for(int i=0;i<7;i++){Matrix p,u,v,w,y;if(!ld("DELTA_THETA_POINT"+std::to_string(i)+"_PARAM.txt",&p)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_A_HESS_AA.txt",&u)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_A_HESS_AR.txt",&v)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_A_HESS_RA.txt",&w)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_A_HESS_RR.txt",&y))return 2;auto d=compute_a_second_derivatives(c,{s,z,x},k,{g,mu,sg,p(0,0),p(1,0),p(2,0)});aa=std::max(aa,max_abs_diff(d.aa,u));ar=std::max(ar,max_abs_diff(d.ar,v));ra=std::max(ra,max_abs_diff(d.ra,w));rr=std::max(rr,max_abs_diff(d.rr,y));sy=std::max(sy,max_abs_diff(d.ar,d.ra));}double mx=std::max({aa,ar,ra,rr});std::cout<<"A_HESS_AA_MAX_ABS_ERROR="<<aa<<"\nA_HESS_AR_MAX_ABS_ERROR="<<ar<<"\nA_HESS_RA_MAX_ABS_ERROR="<<ra<<"\nA_HESS_RR_MAX_ABS_ERROR="<<rr<<"\nA_HESS_MAX_ABS_ERROR="<<mx<<"\nA_HESS_SYMMETRY_MAX_ABS_ERROR="<<sy<<"\nA_HESS_PARITY="<<(mx<=1e-10?"PASS":"FAIL")<<"\n";return mx<=1e-10?0:1;}
